# shellcheck shell=bash
# Shared helpers for the Linear adapter — sourced by every verb script.
# GENERATED by /work-items:onboard-adapter from templates/common.sh.tmpl. This file
# is yours now: it lands in your repo, under your review and CI. Regenerating
# overwrites it, so keep provider-specific logic in the verb scripts.
#
# Contract: tools/work-item-tracker/CONTRACT.md ("Adapter contract", "JSON output
# contract", "Exit codes"). Auth: a Linear API key sent as the bare `Authorization` value, with no scheme word — the credential is read from
# the env var NAMED BY config.linear.auth_env, never stored in the tracked
# binding, and passed to curl through a stdin config (-K -) so it never appears in
# argv (visible to every other process on the machine via /proc and `ps`).
# HTTP goes through ${WIT_LINEAR_CURL:-curl}; tests inject a mock binary
# there to exercise the read path offline.
#
# shellcheck disable=SC2016  # every single-quoted `$name` in this file is a GraphQL or jq variable, never a shell one — that is exactly why the documents are single-quoted, so the shell cannot touch them

[[ -n "${_WIT_LINEAR_COMMON_LOADED:-}" ]] && return 0
readonly _WIT_LINEAR_COMMON_LOADED=1

WIT_LINEAR_ADAPTER_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
readonly WIT_LINEAR_ADAPTER_DIR

# Seam libraries. This adapter lives in the CONSUMING repo while the engine
# dispatching it lives in the read-only plugin directory, so its own ../../lib may
# not exist at all. The dispatcher exports WIT_SEAM_LIB_DIR (CONTRACT.md "Adapter
# resolution") naming the lib/ of the engine actually dispatching — and the engine
# whose contract version this adapter's manifest just handshook against. Fall back
# to the relative path for a vendored seam or a direct (non-dispatched) run. A
# missing lib is a hard failure with a clear diagnostic (exit 3 — setup/config),
# never a silent sourcing failure leaving a verb emitting a malformed record. Runs
# before the EX_* constants below exist, so it uses the literal.
WIT_LINEAR_SEAM_LIB="${WIT_SEAM_LIB_DIR:-$WIT_LINEAR_ADAPTER_DIR/../../lib}"
readonly WIT_LINEAR_SEAM_LIB

wit_linear_require_seam_lib() {
  [[ -f "$1" ]] && return 0
  printf 'work-item-tracker linear adapter: required seam library not found: %s\n' "$1" >&2
  printf '  set WIT_SEAM_LIB_DIR to the work-item-tracker lib/ directory, or vendor the seam\n' >&2
  exit 3
}

# The `shellcheck source=` hints name the RELATIVE seam path rather than /dev/null:
# where a vendored or bundled seam sits there, ShellCheck follows it and every
# WIT_ID_* / WIT_SCHEMA_VERSION reference in this adapter's verb scripts resolves.
# Where it does not (a consumer-local adapter beside no vendored seam), ShellCheck
# resolves. Where it does not, SC1091 is disabled so the absence is quiet rather than
# an info per source line — the runtime check above is what actually enforces presence.
wit_linear_require_seam_lib "$WIT_LINEAR_SEAM_LIB/id.sh"
# shellcheck source=../../lib/id.sh disable=SC1091
source "$WIT_LINEAR_SEAM_LIB/id.sh"
wit_linear_require_seam_lib "$WIT_LINEAR_SEAM_LIB/json.sh"
# shellcheck source=../../lib/json.sh disable=SC1091
source "$WIT_LINEAR_SEAM_LIB/json.sh"
# binding.sh is sourced, not inherited: the dispatcher runs each verb as a fresh
# `bash <verb>.sh` subprocess, so only exported env vars cross — not wit_find_binding.
# The adapter re-locates the binding itself to read its own config subtree.
wit_linear_require_seam_lib "$WIT_LINEAR_SEAM_LIB/binding.sh"
# shellcheck source=../../lib/binding.sh disable=SC1091
source "$WIT_LINEAR_SEAM_LIB/binding.sh"

readonly EX_INTERNAL=1
readonly EX_USAGE=2
readonly EX_CONFIG=3
readonly EX_AUTH=4
readonly EX_NOT_FOUND=5
readonly EX_CONFLICT=7
readonly EX_UNAVAILABLE=8

# HTTP command indirection: the sole testability seam. Tests point
# WIT_LINEAR_CURL at a mock returning canned responses, keeping every
# verb path offline. Absent → real curl.
readonly WIT_LINEAR_CURL_BIN="${WIT_LINEAR_CURL:-curl}"

# config.linear.host becomes the request host that RECEIVES the credential,
# so it must be a BARE hostname — no scheme, path, userinfo (`@`), port, or control
# characters — lest a binding smuggle URL structure that redirects the token off the
# intended tenant. A tracked binding is PR-modifiable and the token may be present in
# CI, so host is additionally pinned by SUFFIX where a pin exists.
#
# The effective pin is, in order: config.linear.host_suffix from the binding
# (the consumer's own pin — the override seam), else the generated default below. A
# non-empty pin denies by default; config.linear.allow_custom_domain=true is
# the explicit, diffable opt-out. An EMPTY generated default means this provider is
# self-hosted and has no vendor domain to pin against — the consumer can still pin
# their own instance via the binding key, and the adapter README records that as a
# stated posture rather than leaving it implied.
readonly WIT_LINEAR_HOSTNAME_RE='^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?$'
readonly WIT_LINEAR_DEFAULT_HOST_SUFFIX='.linear.app'

# wit_linear_host_under_pin <host> <suffix> — is <host> genuinely under the pin?
#
# A bare `*"$suffix"` glob is a plain "ends with", which is NOT a domain boundary: a pin
# of `mycompany.com` is satisfied by `evilmycompany.com`. The shipped default above
# carries its own dot and is safe, but the pin is a consumer override seam, and a
# dot-less override reopens the bypass.
#
# Normalize to a dot-led pin, and accept the apex separately: under a pin of
# `mycompany.com`, the host `mycompany.com` IS the pinned domain even though it does not
# end in `.mycompany.com`.
wit_linear_host_under_pin() {
  local host="$1" pin="$2"
  [[ "$pin" == .* ]] || pin=".$pin"
  [[ "$host" == *"$pin" || "$host" == "${pin#.}" ]]
}
# auth_env is dereferenced via ${!name}; an invalid identifier aborts bash, so it
# must be a valid shell variable name.
readonly WIT_LINEAR_ENV_NAME_RE='^[A-Za-z_][A-Za-z0-9_]*$'
# Scope entries are interpolated into request paths and/or query strings, so they are
# constrained to an allowlist BEFORE interpolation. Allowlisting (reject the
# unexpected) is safer than escaping: an escaping bug is silent, a rejection is loud.
readonly WIT_LINEAR_SCOPE_RE='^[a-z0-9][a-z0-9-]*/[A-Z][A-Z0-9]*$'

# WorkflowState.type is one of triage | backlog | unstarted | started | completed |
# canceled | duplicate (schema.graphql, WorkflowState.type). Everything outside the
# "done" set below normalizes to open. Overridable via config.linear.done_state_types —
# the same override seam the jira adapter gives its statusCategory keys, so this adapter
# is independent of the classification rather than betting on it.
WIT_LINEAR_DEFAULT_DONE_TYPES="$(jq -cn '["completed","canceled","duplicate"]')"
readonly WIT_LINEAR_DEFAULT_DONE_TYPES

# Page size for every connection this adapter reads. Linear's `first` is capped at 250
# by the API; 50 keeps a single response small enough to stay well inside the
# complexity budget on issue queries that also fetch labels and relations.
readonly WIT_LINEAR_DEFAULT_PAGE_SIZE=50
# The total list-items pages up to, matching limits.list_items_max in capabilities.json.
# shellcheck disable=SC2034  # read by list-items.sh; this file is sourced-only
readonly WIT_LINEAR_LIST_ITEMS_MAX=1000

# The lease marker (CONTRACT.md "Lease protocol"). Linear comments carry markdown
# bodies, so the marker rides in the body exactly as it does on GitHub.
readonly WIT_LINEAR_LEASE_PREFIX='<!-- work-item-lease v1 '
readonly WIT_LINEAR_LEASE_SUFFIX=' -->'

# Set by wit_linear_http; declared here so a read before the first call
# does not trip `set -u`.
WIT_LINEAR_BODY=""
WIT_LINEAR_STATUS=""

wit_usage_error() {
  printf '%s: %s\n' "$(basename "${BASH_SOURCE[1]}")" "$1" >&2
  exit "$EX_USAGE"
}

# wit_linear_unimplemented <verb> — the marker a freshly generated verb
# script carries until its provider mapping is filled in. Exit 1 (internal), NOT 6:
# exit 6 means "this provider cannot do it and the manifest says so", which is a
# permanent, honest degradation the caller may route around. An unfilled scaffold is
# neither — declaring it 6 would launder unfinished work as a provider limitation, and
# the conformance suite would pass on a verb that does nothing. Any verb still
# reaching this line either needs its mapping written or needs `false` in
# capabilities.json.
wit_linear_unimplemented() {
  printf '%s: linear adapter verb %s is a generated scaffold with no provider mapping yet\n' \
    "$(basename "${BASH_SOURCE[1]}")" "$1" >&2
  printf '  fill in its PROVIDER MAPPING block, or set verbs["%s"]=false in capabilities.json\n' "$1" >&2
  exit "$EX_INTERNAL"
}

# wit_help_if_requested <usage-text> <args…> — print usage + exit 0 on --help.
wit_help_if_requested() {
  local usage="$1"
  shift
  if [[ "${1:-}" == "--help" ]]; then
    printf '%s\n' "$usage"
    exit 0
  fi
}

# wit_linear_nonempty_array <json-text> — 0 when the text is a non-empty
# JSON array. Type is checked before length so a scalar such as "scopes":"abc" cannot
# pass on its string length; jq's `and` short-circuits, so `length` never runs on a
# non-array.
wit_linear_nonempty_array() {
  [[ "$(jq -r 'if (type == "array" and length > 0) then "yes" else "no" end' <<<"$1")" == "yes" ]]
}

# wit_linear_bad_elements <anchored-regex> <json-array> — the array's
# elements that are not strings matching the allowlist, as a JSON array (`[]` when all
# are valid). The type guard sits left of the `or` so test() never runs on a
# non-string. Checked IN jq rather than a bash line-loop: command substitution strips
# trailing newlines, so `[""]` would evade a loop.
wit_linear_bad_elements() {
  jq -rc --arg re "$1" '[.[] | select((type != "string") or (test($re) | not))]' <<<"$2"
}

# wit_require_linear_id <id> — parse an ID and require its provider be
# `linear`. The shared grammar accepts any provider; this adapter rejects
# foreign-provider IDs so a `github:…#N` never operates on a Linear item.
# Sets the WIT_ID_* globals.
# shellcheck disable=SC2154  # WIT_ID_PROVIDER is exported by wit_parse_id in the seam's id.sh, sourced above through a runtime-resolved path ShellCheck cannot follow
wit_require_linear_id() {
  wit_parse_id "$1" || return 1
  [[ "$WIT_ID_PROVIDER" == "linear" ]] || return 1
}

# wit_need_linear_config — load and validate the linear config
# subtree from the binding. Call AFTER arg parsing, so --help and usage errors stay
# offline and config-free. Exits 3 on any missing or invalid key.
# Exports WIT_LINEAR_HOST, WIT_LINEAR_SCOPES (JSON array),
# WIT_LINEAR_AUTH_ENV.
wit_need_linear_config() {
  local name binding ejson
  name="$(basename "${BASH_SOURCE[1]}")"
  binding="$(wit_find_binding)" ||
    {
      printf '%s: no binding found (.work-item-tracker.json) — see CONTRACT.md Setup\n' "$name" >&2
      exit "$EX_CONFIG"
    }
  ejson="$(wit_effective_binding_json "$binding")" ||
    {
      printf '%s: invalid binding at %s — see CONTRACT.md Setup\n' "$name" "$binding" >&2
      exit "$EX_CONFIG"
    }
  WIT_LINEAR_HOST="$(jq -r '.config.linear.host // empty' <<<"$ejson")"
  WIT_LINEAR_AUTH_ENV="$(jq -r '.config.linear.auth_env // empty' <<<"$ejson")"
  WIT_LINEAR_SCOPES="$(jq -c '.config.linear.scopes // []' <<<"$ejson")"
  # Read by PRESENCE, not `//`: jq's `//` collapses an explicit null or false into the
  # default, which would silently apply the DEFAULT classification for a typo'd override
  # instead of the required config error. Absent → default; present → taken verbatim so
  # the type and non-empty checks below judge it.
  if [[ "$(jq -r '.config.linear | has("done_state_types")' <<<"$ejson")" == "true" ]]; then
    WIT_LINEAR_DONE_TYPES="$(jq -c '.config.linear.done_state_types' <<<"$ejson")"
  else
    WIT_LINEAR_DONE_TYPES="$WIT_LINEAR_DEFAULT_DONE_TYPES"
  fi
  if [[ "$(jq -r '.config.linear | has("page_size")' <<<"$ejson")" == "true" ]]; then
    WIT_LINEAR_PAGE_SIZE="$(jq -r '.config.linear.page_size' <<<"$ejson")"
  else
    WIT_LINEAR_PAGE_SIZE="$WIT_LINEAR_DEFAULT_PAGE_SIZE"
  fi
  WIT_LINEAR_LEASE_TTL_HOURS="$(jq -r '.config.lease_ttl_hours // 24' <<<"$ejson")"
  WIT_LINEAR_LEASE_TTL_MINUTES="$(jq -r '.config.lease_ttl_minutes // 0' <<<"$ejson")"

  local allow_custom_domain host_suffix
  allow_custom_domain="$(jq -r '.config.linear.allow_custom_domain // false' <<<"$ejson")"
  host_suffix="$(jq -r --arg d "$WIT_LINEAR_DEFAULT_HOST_SUFFIX" '.config.linear.host_suffix // $d' <<<"$ejson")"

  local missing=""
  [[ -n "$WIT_LINEAR_HOST" ]] || missing+=" config.linear.host"
  [[ -n "$WIT_LINEAR_AUTH_ENV" ]] || missing+=" config.linear.auth_env"

  # scopes must be a non-empty ARRAY, not merely truthy: a scalar such as
  # "scopes":"acme/webapp" would satisfy a bare `length > 0` on its string length,
  # then `.[]`/`map(...)` would jq-error into an empty clause this non-`set -e`
  # script would otherwise ignore.
  wit_linear_nonempty_array "$WIT_LINEAR_SCOPES" ||
    missing+=" config.linear.scopes[](non-empty array)"
  if [[ -n "$missing" ]]; then
    printf '%s: linear binding missing/invalid required config:%s — see the adapter README\n' "$name" "$missing" >&2
    exit "$EX_CONFIG"
  fi

  # Value-level validation (all exit 3): the credential-bearing host, the token env
  # var name, and every interpolated scope entry against its allowlist charset.
  local bad=""
  if ! [[ "$WIT_LINEAR_HOST" =~ $WIT_LINEAR_HOSTNAME_RE ]]; then
    bad+=" host:'$WIT_LINEAR_HOST'(not a bare hostname)"
  elif [[ -n "$host_suffix" && "$allow_custom_domain" != "true" ]] &&
    ! wit_linear_host_under_pin "$WIT_LINEAR_HOST" "$host_suffix"; then
    bad+=" host:'$WIT_LINEAR_HOST'(not under $host_suffix; set config.linear.allow_custom_domain=true to allow)"
  fi
  [[ "$WIT_LINEAR_AUTH_ENV" =~ $WIT_LINEAR_ENV_NAME_RE ]] ||
    bad+=" auth_env:'$WIT_LINEAR_AUTH_ENV'(not a valid env var name)"
  local bad_scopes
  bad_scopes="$(wit_linear_bad_elements "$WIT_LINEAR_SCOPE_RE" "$WIT_LINEAR_SCOPES")"
  [[ "$bad_scopes" == "[]" ]] || bad+=" scopes:$bad_scopes"
  # One API key authenticates against exactly one workspace, so scopes naming two
  # different workspaces describe something this binding cannot reach. Refusing is
  # better than silently succeeding for one prefix and 404-ing on the other.
  if [[ "$(jq -r '[.[] | split("/")[0]] | unique | length' <<<"$WIT_LINEAR_SCOPES")" != "1" ]]; then
    bad+=" scopes(all entries must share one workspace — an API key reaches exactly one)"
  fi
  # An empty done-set would classify every state as open, so a claimed item's completion
  # would never be visible to the frontier. A present-but-wrong value is a config error,
  # not a fall-through to the default.
  wit_linear_nonempty_array "$WIT_LINEAR_DONE_TYPES" ||
    bad+=" done_state_types(must be a non-empty array)"
  # Bounded, not just positive. Linear caps every connection's `first` at 250
  # (WIT_LINEAR_DEFAULT_PAGE_SIZE's comment above says so), so an unbounded check accepts a
  # page_size the API rejects — config validation passes and the FIRST live call fails, which
  # is the failure mode config validation exists to prevent. Caught by validating the adapter's
  # operations against Linear's published schema; every read verb passes this value as `first`.
  if [[ "$WIT_LINEAR_PAGE_SIZE" =~ ^[1-9][0-9]*$ ]]; then
    [[ "$WIT_LINEAR_PAGE_SIZE" -le 250 ]] ||
      bad+=" page_size:'$WIT_LINEAR_PAGE_SIZE'(exceeds linear's cap of 250 for a connection's first)"
  else
    bad+=" page_size:'$WIT_LINEAR_PAGE_SIZE'(must be a positive integer)"
  fi
  # TTLs bound lease liveness arithmetic; a non-integer would make every comparison
  # error out and silently read as "not live", handing every item to the next claimer.
  [[ "$WIT_LINEAR_LEASE_TTL_HOURS" =~ ^[0-9]+$ ]] ||
    bad+=" lease_ttl_hours:'$WIT_LINEAR_LEASE_TTL_HOURS'(must be a non-negative integer)"
  [[ "$WIT_LINEAR_LEASE_TTL_MINUTES" =~ ^[0-9]+$ ]] ||
    bad+=" lease_ttl_minutes:'$WIT_LINEAR_LEASE_TTL_MINUTES'(must be a non-negative integer)"
  if [[ -n "$bad" ]]; then
    printf '%s: invalid linear config value(s):%s — see the adapter README\n' "$name" "$bad" >&2
    exit "$EX_CONFIG"
  fi

  # curl is the only prerequisite binary; gate here (exit 3, actionable) rather than
  # let the first request fail obscurely. The bin is the real curl by default or a
  # test-injected mock — either way it must resolve.
  command -v "$WIT_LINEAR_CURL_BIN" >/dev/null 2>&1 ||
    {
      printf '%s: prerequisite missing: curl (Linear REST over HTTPS) — see CONTRACT.md Prerequisites\n' "$name" >&2
      exit "$EX_CONFIG"
    }
  export WIT_LINEAR_HOST WIT_LINEAR_AUTH_ENV WIT_LINEAR_SCOPES WIT_LINEAR_DONE_TYPES \
    WIT_LINEAR_PAGE_SIZE WIT_LINEAR_LEASE_TTL_HOURS WIT_LINEAR_LEASE_TTL_MINUTES
}

# wit_linear_scope_in_scope <entry> — 0 when the entry is in the binding's
# config.linear.scopes. That list is the declared read scope AND the
# authorization boundary: a bound workflow must not read items from a scope it did not
# declare, even when the token can see them. Each verb enforces it BEFORE any request,
# mapping a miss to its own usage error (exit 2) so the diagnostic names the verb.
wit_linear_scope_in_scope() {
  [[ "$(jq -r --arg k "$1" 'if (index($k) != null) then "in" else "out" end' <<<"$WIT_LINEAR_SCOPES")" == "in" ]]
}

# wit_linear_token — echo the credential from the env var NAMED BY
# config.linear.auth_env. Exits 4 (auth) when that env var is unset or empty:
# the token is never stored in the tracked binding, only referenced by name. Call
# after wit_need_linear_config.
wit_linear_token() {
  local token="${!WIT_LINEAR_AUTH_ENV:-}"
  if [[ -z "$token" ]]; then
    printf '%s: linear credential env var %s is unset or empty (config.linear.auth_env)\n' \
      "$(basename "${BASH_SOURCE[1]}")" "$WIT_LINEAR_AUTH_ENV" >&2
    exit "$EX_AUTH"
  fi
  printf '%s' "$token"
}

# wit_linear_auth_header — the Authorization header line. Built here and fed
# to curl through the stdin config, so the credential never reaches argv. This provider
# takes the key as the bare header value: no scheme word, and no leading space.
wit_linear_auth_header() {
  local token
  token="$(wit_linear_token)" || exit "$?"
  printf 'Authorization: %s' "$token"
}

# wit_linear_http <method> <path> [<json-body>] — call
# https://<host>/graphql<path>. The Authorization header is fed through curl's
# stdin config (-K -) so the credential never appears in argv. `--proto '=https'`
# refuses any non-HTTPS scheme, and redirects are NOT followed (no -L), so the header
# can never be replayed to a host the binding did not authorize. Captures the response
# body to WIT_LINEAR_BODY and the HTTP status to
# WIT_LINEAR_STATUS; on a curl transport failure (no status) exits 8.
# HTTP-status→exit-code mapping is left to the caller via
# wit_linear_require_ok so it can attach verb-specific context.
wit_linear_http() {
  local method="$1" path="$2" body="${3:-}"
  local url="https://$WIT_LINEAR_HOST/graphql$path"
  local auth raw rc
  auth="$(wit_linear_auth_header)" || exit "$?"
  local curl_args=(-sS -X "$method" -H "Accept: application/json" --proto '=https' -w $'\n%{http_code}' -K -)
  if [[ -n "$body" ]]; then
    curl_args+=(-H "Content-Type: application/json" --data "$body")
  fi
  raw="$(printf 'header = "%s"\nurl = "%s"\n' "$auth" "$url" |
    "$WIT_LINEAR_CURL_BIN" "${curl_args[@]}" 2>/dev/null)"
  rc=$?
  if ((rc != 0)); then
    printf 'linear: request to %s failed (curl exit %s) — network or endpoint unavailable\n' "$path" "$rc" >&2
    exit "$EX_UNAVAILABLE"
  fi
  WIT_LINEAR_STATUS="${raw##*$'\n'}"
  WIT_LINEAR_BODY="$(printf '%s' "${raw%$'\n'*}" | wit_strip_cr)"
}

# wit_linear_require_ok <context> — map WIT_LINEAR_STATUS to a
# contract exit code, printing the provider's error text to stderr on failure. 2xx
# returns 0.
wit_linear_require_ok() {
  local ctx="$1" code="$WIT_LINEAR_STATUS"
  case "$code" in
  2*) return 0 ;;
  401 | 403)
    printf 'linear: %s — authentication/authorization failed (HTTP %s)\n' "$ctx" "$code" >&2
    exit "$EX_AUTH"
    ;;
  404)
    printf 'linear: %s — not found (HTTP 404)\n' "$ctx" >&2
    exit "$EX_NOT_FOUND"
    ;;
  409 | 412 | 422)
    printf 'linear: %s — conflict/precondition (HTTP %s)\n' "$ctx" "$code" >&2
    exit "$EX_CONFLICT"
    ;;
  429)
    printf 'linear: %s — rate limited (HTTP 429); retry later\n' "$ctx" >&2
    exit "$EX_UNAVAILABLE"
    ;;
  5*)
    printf 'linear: %s — server error (HTTP %s)\n' "$ctx" "$code" >&2
    exit "$EX_UNAVAILABLE"
    ;;
  *)
    printf 'linear: %s — unexpected response (HTTP %s): %s\n' "$ctx" "$code" "$WIT_LINEAR_BODY" >&2
    exit "$EX_INTERNAL"
    ;;
  esac
}

# --- GraphQL transport -------------------------------------------------------------
#
# Linear has ONE endpoint (POST https://api.linear.app/graphql) rather than a REST path
# space, so wit_linear_http's method/path arguments are always POST and "". Everything
# below goes through wit_linear_gql instead, which adds the thing a REST-shaped helper
# cannot know about:
#
#   **A GraphQL error arrives with HTTP 200.** `{"errors":[…]}` beside a null `data` is
#   a 200 response, so wit_linear_require_ok alone would wave a failed mutation through
#   and the verb would emit a malformed record. wit_linear_gql inspects `errors` and
#   maps them to the contract's exit codes before any caller sees `data`.

# The GraphQL fields every normalized item is built from. One place, so a query that
# forgets `state { type }` cannot silently normalize every item to "open".
# shellcheck disable=SC2034  # consumed by the verb scripts; this file is sourced-only
readonly WIT_LINEAR_ISSUE_FIELDS='
  id
  identifier
  number
  title
  url
  state { type name }
  assignee { displayName email }
  labels(first: 50) { nodes { name } }
  parent { identifier team { key } number }
  team { key }
  inverseRelations(first: 100) { nodes { type issue { state { type } } } }
'

# The `data` object from the most recent wit_linear_gql call — read by the verb
# scripts, which is why ShellCheck cannot see it used from inside this sourced lib.
# shellcheck disable=SC2034
WIT_LINEAR_DATA=""

# wit_linear_gql <query> <variables-json> [<context>] — run one GraphQL operation.
# Sets WIT_LINEAR_DATA to the response's `data`. Exits on transport failure, on an HTTP
# error status, or on a GraphQL `errors` array.
wit_linear_gql() {
  local query="$1" vars="${2:-{\}}" ctx="${3:-graphql request}"
  local payload
  payload="$(jq -cn --arg q "$query" --argjson v "$vars" '{query: $q, variables: $v}')"
  wit_linear_http POST "" "$payload"
  wit_linear_require_ok "$ctx"

  local errors
  errors="$(jq -c '.errors // []' <<<"$WIT_LINEAR_BODY" 2>/dev/null)" || errors='[]'
  if [[ "$errors" != "[]" ]]; then
    local first_msg first_code
    first_msg="$(jq -r '.[0].message // "unknown GraphQL error"' <<<"$errors")"
    # Linear tags errors with a machine-readable type under extensions; map the ones
    # that mean something specific to the contract, and let the rest be internal.
    first_code="$(jq -r '.[0].extensions.type // .[0].extensions.code // ""' <<<"$errors")"
    printf 'linear: %s — %s\n' "$ctx" "$first_msg" >&2
    # Matched case-insensitively on the lowercased code, so one pattern per meaning
    # covers Linear's mixed spellings (`authenticationError`, `AuthenticationError`,
    # `ratelimited`, …) without patterns that shadow each other.
    case "$(printf '%s' "$first_code" | tr '[:upper:]' '[:lower:]')" in
    *authentication* | *forbidden* | *unauthorized*) exit "$EX_AUTH" ;;
    *notfound* | *not_found*) exit "$EX_NOT_FOUND" ;;
    *ratelimit* | *unavailable*) exit "$EX_UNAVAILABLE" ;;
    *) exit "$EX_INTERNAL" ;;
    esac
  fi

  # shellcheck disable=SC2034  # read by the verb scripts that call this helper
  WIT_LINEAR_DATA="$(jq -c '.data // {}' <<<"$WIT_LINEAR_BODY" 2>/dev/null)" || {
    printf 'linear: %s — response carried no JSON data object\n' "$ctx" >&2
    exit "$EX_INTERNAL"
  }
}

# --- normalization -----------------------------------------------------------------

# wit_linear_normalize_program — a jq program mapping ONE raw Linear `Issue` (selected
# with WIT_LINEAR_ISSUE_FIELDS) into the seam's normalized item object (CONTRACT.md
# "JSON output contract"). Expects jq args $sv (schema version), $ws (workspace slug),
# and $dt (JSON array of done WorkflowState types).
#
# Field names verified against Linear's published GraphQL schema
# (`packages/sdk/src/schema.graphql` in linear/linear), not from memory:
#   • `number` is the team-scoped issue number and `team.key` its team prefix — together
#     they are `identifier` ("ENG-123"). `id` is a UUID and is deliberately NOT the
#     seam id: no URL resolves it and it is unreadable in a tracker comment.
#   • The workspace is a jq ARG rather than a field: Linear's Issue exposes no
#     workspace/organization on this selection, and one API key reaches exactly one
#     workspace, so the binding is the authority for that half of the id.
#   • `state` is a WorkflowState whose `type` is the stable axis — triage | backlog |
#     unstarted | started | completed | canceled | duplicate. `name` is user-renameable
#     per team and must never be classified on.
#   • `assignee` is a SINGLE field, not a list. The normalized `assignees` array
#     therefore holds zero or one entry. (This is also why the claim protocol below
#     cannot use GitHub's assignee-collision check.)
#   • `inverseRelations` are the relations where THIS issue is the target, so a
#     `blocks` relation there means the other issue blocks this one — which is exactly
#     blocked_by. `relations` is the opposite direction and would invert every edge.
#   • Linear has no issue-TYPE axis in the contract's sense (its "type" here is the
#     workflow-state category), so normalized `type` is null.
# shellcheck disable=SC2016,SC2034  # jq program — $sv/$ws/$dt are jq args, not bash; used by verb scripts
readonly WIT_LINEAR_NORMALIZE_PROGRAM='
  def is_done($t): ($dt | index($t)) != null;
  def qualify(team; num): "linear:" + $ws + "/" + team + "#" + (num | tostring);
  {
    schema_version: $sv,
    id: qualify(.team.key // ""; .number),
    title: (.title // ""),
    state: (if is_done(.state.type // "") then "closed" else "open" end),
    assignees: [ (.assignee.displayName // .assignee.email // empty) ],
    labels: [ (.labels.nodes // [])[] | .name // empty ],
    type: null,
    blocked_by_count: ([ (.inverseRelations.nodes // [])[]
      | select(.type == "blocks")
      | select(is_done(.issue.state.type // "") | not) ] | length),
    parent_id: (if (.parent // null) == null then null
                else qualify(.parent.team.key // ""; .parent.number) end),
    url: (.url // "")
  }'

# wit_linear_scope_parts <workspace/TEAM> — split a scope entry, setting
# WIT_LINEAR_WS and WIT_LINEAR_TEAM. The entry has already passed
# WIT_LINEAR_SCOPE_RE, which guarantees exactly one slash and a strict charset on both
# halves, so neither is escaped again downstream.
# shellcheck disable=SC2034  # WIT_LINEAR_WS/TEAM are read by the verb scripts
wit_linear_scope_parts() {
  WIT_LINEAR_WS="${1%%/*}"
  WIT_LINEAR_TEAM="${1#*/}"
}

# wit_linear_workspace — the one workspace this binding reaches. Validation has already
# refused a scopes list spanning more than one, so the first entry is authoritative.
wit_linear_workspace() { jq -r '.[0] | split("/")[0]' <<<"$WIT_LINEAR_SCOPES"; }

# wit_linear_normalize <raw-issue-json> — the normalized item object for one Issue.
wit_linear_normalize() {
  jq -c --arg sv "$WIT_SCHEMA_VERSION" --arg ws "$(wit_linear_workspace)" \
    --argjson dt "$WIT_LINEAR_DONE_TYPES" \
    "$WIT_LINEAR_NORMALIZE_PROGRAM" <<<"$1"
}

# wit_linear_fetch_issue <TEAMKEY> <number> — set WIT_LINEAR_ISSUE to that issue's raw
# GraphQL node. Exits 5 when no such issue exists.
#
# Addressed by (team key, number) rather than by `identifier`: Linear has no
# issue-by-identifier query, and the UUID `id` is not what the seam's ids carry. The
# filter is sent as VARIABLES, never interpolated into the query text — the team key
# comes from a validated scope, but building queries by concatenation is the habit that
# eventually meets an unvalidated value.
# shellcheck disable=SC2034  # WIT_LINEAR_ISSUE is read by the verb scripts
wit_linear_fetch_issue() {
  local team="$1" number="$2" q
  q="query(\$team: String!, \$num: Float!) {
    issues(filter: { team: { key: { eq: \$team } }, number: { eq: \$num } }, first: 1) {
      nodes { $WIT_LINEAR_ISSUE_FIELDS }
    }
  }"
  wit_linear_gql "$q" \
    "$(jq -cn --arg t "$team" --argjson n "$number" '{team: $t, num: $n}')" \
    "fetching $team-$number"
  WIT_LINEAR_ISSUE="$(jq -c '.issues.nodes[0] // empty' <<<"$WIT_LINEAR_DATA")"
  if [[ -z "$WIT_LINEAR_ISSUE" ]]; then
    printf 'linear: %s-%s not found in workspace %s\n' "$team" "$number" "$(wit_linear_workspace)" >&2
    exit "$EX_NOT_FOUND"
  fi
}

# wit_linear_require_scoped_id <id> — parse an id, require the linear provider, and
# require its workspace/team be in the declared scope list. The scope list is the
# authorization boundary, not a filter: a bound workflow must not touch an item in a
# team it never declared, even when the API key can see it. Sets the WIT_ID_* globals
# plus WIT_LINEAR_WS / WIT_LINEAR_TEAM.
wit_linear_require_scoped_id() {
  wit_require_linear_id "$1" || wit_usage_error "not a linear item id: $1"
  wit_linear_scope_in_scope "$WIT_ID_OWNER/$WIT_ID_REPO" ||
    wit_usage_error "$WIT_ID_OWNER/$WIT_ID_REPO is not in config.linear.scopes (the declared scope)"
  wit_linear_scope_parts "$WIT_ID_OWNER/$WIT_ID_REPO"
}

# --- lease helpers (CONTRACT.md "Lease protocol") ------------------------------------

# wit_linear_now_iso — current UTC time in the marker's ISO-8601 form.
wit_linear_now_iso() { date -u +%Y-%m-%dT%H:%M:%SZ; }

# wit_linear_epoch <iso-8601> — that timestamp as epoch seconds, or empty when it
# cannot be parsed. GNU date and BSD/macOS date disagree on the flag, so both are tried;
# an unparsable timestamp returns empty and every caller treats that as "not live",
# which fails toward refusing to renew rather than toward reviving a dead lease.
#
# Fractional seconds are stripped HERE rather than by each caller. Linear returns
# `createdAt` with milliseconds while this adapter's own markers write whole seconds, so
# callers see both forms; a caller that stripped them by assuming a `.` was present
# would corrupt the whole-second form instead — which is exactly how an activity check
# once silently saw no activity at all.
wit_linear_epoch() {
  local ts="$1"
  case "$ts" in
  *.*) ts="${ts%%.*}Z" ;;
  *) ;;
  esac
  # portability-ok: GNU-first rung of a dual-dialect ladder — the BSD `-j -f` spelling follows,
  # and an empty `printf` is the third rung. The `case` above normalizes the fractional form off
  # the timestamp precisely so the BSD rung's exact-match `-f` format can parse it.
  date -u -d "$ts" +%s 2>/dev/null || date -u -j -f '%Y-%m-%dT%H:%M:%SZ' "$ts" +%s 2>/dev/null || printf ''
}

# wit_linear_lease_marker <json> — the comment body carrying that lease record.
wit_linear_lease_marker() {
  printf '%s%s%s' "$WIT_LINEAR_LEASE_PREFIX" "$1" "$WIT_LINEAR_LEASE_SUFFIX"
}

# wit_linear_lease_json <comment-body> — the marker's JSON, or empty when the body
# carries no lease marker.
wit_linear_lease_json() {
  local body="$1" rest
  [[ "$body" == *"$WIT_LINEAR_LEASE_PREFIX"* ]] || return 1
  rest="${body#*"$WIT_LINEAR_LEASE_PREFIX"}"
  rest="${rest%%"$WIT_LINEAR_LEASE_SUFFIX"*}"
  jq -e -c . <<<"$rest" 2>/dev/null
}

# wit_linear_lease_live <lease-json> — 0 when the lease has no superseded_at and its
# renewed_at plus TTL is still in the future. An unparsable or missing renewed_at is
# NOT live: a lease whose expiry cannot be computed must not hold an item forever.
wit_linear_lease_live() {
  local lease="$1" superseded renewed epoch ttl now
  superseded="$(jq -r '.superseded_at // empty' <<<"$lease")"
  [[ -z "$superseded" ]] || return 1
  renewed="$(jq -r '.renewed_at // empty' <<<"$lease")"
  [[ -n "$renewed" ]] || return 1
  epoch="$(wit_linear_epoch "$renewed")"
  [[ -n "$epoch" ]] || return 1
  ttl=$(($(jq -r '.ttl_hours // 0' <<<"$lease") * 3600 + $(jq -r '.ttl_minutes // 0' <<<"$lease") * 60))
  now="$(date -u +%s)"
  ((epoch + ttl > now))
}

# wit_linear_handle <iso-8601> — the numeric lease handle for a comment created then.
#
# The contract requires an ORDERED, unique, numeric lease_comment_id, because same-login
# race arbitration treats the lower handle as the winner. Linear's comment ids are UUIDs
# and carry no order, so this adapter follows the local-markdown precedent and mints its
# own handle into the marker JSON — epoch MILLISECONDS of the comment's createdAt, which
# is ordered by construction. Ties within one millisecond are broken on the comment UUID
# by the arbitration itself, so ordering stays total even when handles collide.
wit_linear_handle() {
  local secs frac
  secs="$(wit_linear_epoch "$1")"
  [[ -n "$secs" ]] || {
    printf '0'
    return 0
  }
  # createdAt is ISO-8601 with optional fractional seconds (2026-08-20T05:40:57.123Z).
  case "$1" in
  *.*)
    frac="${1#*.}"
    frac="${frac%Z}"
    frac="$(printf '%s000' "$frac" | cut -c1-3)"
    ;;
  *) frac="000" ;;
  esac
  printf '%s%s' "$secs" "$frac"
}

# wit_linear_resolve_viewer — set WIT_LINEAR_VIEWER (the display name, matching what the
# normalizer puts in `assignees`) and WIT_LINEAR_VIEWER_ID (the UUID the assignment
# mutations need).
#
# Deliberately sets globals rather than echoing: a caller writing
# `holder="$(wit_linear_viewer)"` would run it in a SUBSHELL, and the UUID it also
# resolves would be lost — leaving the next line to fail on an unbound variable, or
# worse, to assign nobody.
#
# The lease holder is ALWAYS this identity — the authenticated session user, never a bot
# or a caller-supplied name — so a claim can never be attributed to someone who did not
# make it.
WIT_LINEAR_VIEWER=""
WIT_LINEAR_VIEWER_ID=""
wit_linear_resolve_viewer() {
  wit_linear_gql 'query { viewer { id displayName email } }' '{}' "resolving the authenticated user"
  WIT_LINEAR_VIEWER_ID="$(jq -r '.viewer.id // empty' <<<"$WIT_LINEAR_DATA")"
  WIT_LINEAR_VIEWER="$(jq -r '.viewer.displayName // .viewer.email // empty' <<<"$WIT_LINEAR_DATA")"
  if [[ -z "$WIT_LINEAR_VIEWER_ID" || -z "$WIT_LINEAR_VIEWER" ]]; then
    printf 'linear: could not resolve the authenticated user from the API key\n' >&2
    exit "$EX_AUTH"
  fi
}

# wit_linear_lease_comments <issue-uuid> — every lease comment on that issue as a JSON
# array of {handle, comment_id, lease}, ordered by handle then comment_id.
#
# That secondary sort is what keeps arbitration TOTAL: handles are millisecond
# timestamps, so two comments created in the same millisecond tie, and a tie with no
# tiebreak would let two racers each believe they won. The comment UUID is arbitrary but
# identical for both observers, which is all arbitration needs.
# wit_linear_activity_since <issue-id> <epoch> — did anyone comment after <epoch>?
# Exit 0 = yes (the holder is demonstrably still working), 1 = no.
#
# Paginates, and that is the whole point. The first-page-only query this replaced could
# not see recent activity at all on a busy item: Linear returns a comments connection
# oldest-first absent an explicit orderBy, so the NEWEST comments — exactly the ones
# that prove a holder is alive — are on the LAST page. Past ~one page of comments the
# check silently reported "no activity" and reclaim released a live lease.
#
# It cannot reuse wit_linear_lease_comments below: that one keeps only lease markers,
# and this one wants precisely the opposite. The adapter's own renewal markers are
# skipped here, or a lease would count its own heartbeat as activity and never expire.
wit_linear_activity_since() {
  local issue_id="$1" since="$2" cursor="" has_next="true" q page node body cepoch
  q='query($id: String!, $first: Int!, $after: String) {
    issue(id: $id) {
      comments(first: $first, after: $after) {
        nodes { body createdAt }
        pageInfo { hasNextPage endCursor }
      }
    }
  }'
  while [[ "$has_next" == "true" ]]; do
    wit_linear_gql "$q" \
      "$(jq -cn --arg id "$issue_id" --argjson f "$WIT_LINEAR_PAGE_SIZE" --arg a "$cursor" \
        '{id: $id, first: $f, after: (if ($a | length) > 0 then $a else null end)}')" \
      "checking activity on $issue_id"
    page="$(jq -c '.issue.comments // {nodes: [], pageInfo: {hasNextPage: false}}' <<<"$WIT_LINEAR_DATA")"
    while IFS= read -r node; do
      [[ -n "$node" ]] || continue
      body="$(jq -r '.body // ""' <<<"$node")"
      [[ "$body" != *"$WIT_LINEAR_LEASE_PREFIX"* ]] || continue
      cepoch="$(wit_linear_epoch "$(jq -r '.createdAt' <<<"$node")")"
      [[ -n "$cepoch" ]] || continue
      if ((cepoch > since)); then
        return 0
      fi
    done < <(jq -c '.nodes[]?' <<<"$page")
    has_next="$(jq -r '.pageInfo.hasNextPage // false' <<<"$page")"
    cursor="$(jq -r '.pageInfo.endCursor // ""' <<<"$page")"
    [[ -n "$cursor" ]] || break
  done
  return 1
}

wit_linear_lease_comments() {
  local issue_id="$1" cursor="" has_next="true" all='[]' q page
  q='query($id: String!, $first: Int!, $after: String) {
    issue(id: $id) {
      comments(first: $first, after: $after) {
        nodes { id body createdAt }
        pageInfo { hasNextPage endCursor }
      }
    }
  }'
  while [[ "$has_next" == "true" ]]; do
    wit_linear_gql "$q" \
      "$(jq -cn --arg id "$issue_id" --argjson f "$WIT_LINEAR_PAGE_SIZE" --arg a "$cursor" \
        '{id: $id, first: $f, after: (if ($a | length) > 0 then $a else null end)}')" \
      "listing comments on $issue_id"
    page="$(jq -c '.issue.comments // {nodes: [], pageInfo: {hasNextPage: false}}' <<<"$WIT_LINEAR_DATA")"
    local node body lease handle cid
    while IFS= read -r node; do
      [[ -n "$node" ]] || continue
      body="$(jq -r '.body // ""' <<<"$node")"
      lease="$(wit_linear_lease_json "$body")" || continue
      cid="$(jq -r '.id' <<<"$node")"
      handle="$(jq -r '.lease_comment_id // empty' <<<"$lease")"
      # A marker with no handle predates this adapter's handle minting (or was written
      # by hand). Fall back to the comment's own createdAt so it still ORDERS rather
      # than being dropped — dropping it would make a live foreign lease invisible.
      # A NON-NUMERIC handle takes the same fallback as a missing one, and for the same
      # reason. `--argjson h` on a non-JSON value makes jq exit 2 printing nothing, which
      # emptied `all`; every later iteration then failed identically on `--argjson acc ""`,
      # and the trailing `sort_by` over empty input printed nothing AND EXITED 0. The
      # helper thus returned success-with-no-output, which every caller reads as "nothing
      # is claimed" — so a live foreign lease became invisible and claim.sh handed out a
      # second lease over it. The `|| exit "$?"` guards at the call sites cannot catch
      # that, because the failure never reaches them as a non-zero status.
      #
      # Markers are consumer-writable in practice (hand-edited, or written by another
      # tool speaking the same v1 shape), so a malformed handle is reachable input, not a
      # theoretical one.
      [[ "$handle" =~ ^[0-9]+$ ]] || handle="$(wit_linear_handle "$(jq -r '.createdAt' <<<"$node")")"
      all="$(jq -c --argjson acc "$all" --argjson h "$handle" --arg c "$cid" --argjson l "$lease" \
        '$acc + [{handle: $h, comment_id: $c, lease: $l}]' <<<'null')" || {
        # Belt and braces: whatever else ever makes this jq fail, it must not degrade to
        # an empty accumulator that reads as "no leases". Fail loudly instead.
        printf 'linear: could not accumulate lease comments on %s — refusing to report an empty lease set\n' \
          "$issue_id" >&2
        exit "$EX_INTERNAL"
      }
    done < <(jq -c '.nodes[]?' <<<"$page")
    has_next="$(jq -r '.pageInfo.hasNextPage // false' <<<"$page")"
    cursor="$(jq -r '.pageInfo.endCursor // ""' <<<"$page")"
    [[ -n "$cursor" ]] || break
  done
  jq -c 'sort_by(.handle, .comment_id)' <<<"$all"
}

# wit_linear_post_comment <issue-uuid> <body> — create a comment, echoing
# {id, createdAt}.
wit_linear_post_comment() {
  wit_linear_gql \
    'mutation($input: CommentCreateInput!) { commentCreate(input: $input) { success comment { id createdAt } } }' \
    "$(jq -cn --arg id "$1" --arg b "$2" '{input: {issueId: $id, body: $b}}')" \
    "posting a comment on $1"
  local out
  out="$(jq -c '.commentCreate.comment // empty' <<<"$WIT_LINEAR_DATA")"
  [[ -n "$out" ]] || {
    printf 'linear: comment creation reported no comment\n' >&2
    exit "$EX_INTERNAL"
  }
  printf '%s' "$out"
}

# wit_linear_update_comment <comment-uuid> <body> — replace a comment's body in place.
# Renew edits the marker rather than posting a new one, so a long-running claim leaves
# ONE lease comment rather than a renewal per heartbeat.
wit_linear_update_comment() {
  wit_linear_gql \
    'mutation($id: String!, $input: CommentUpdateInput!) { commentUpdate(id: $id, input: $input) { success } }' \
    "$(jq -cn --arg id "$1" --arg b "$2" '{id: $id, input: {body: $b}}')" \
    "updating comment $1"
}

# wit_linear_set_assignee <issue-uuid> <user-uuid-or-null> — assign or unassign.
wit_linear_set_assignee() {
  wit_linear_gql \
    'mutation($id: String!, $input: IssueUpdateInput!) { issueUpdate(id: $id, input: $input) { success } }' \
    "$(jq -cn --arg id "$1" --arg u "$2" '{id: $id, input: {assigneeId: (if ($u | length) > 0 then $u else null end)}}')" \
    "setting the assignee on $1"
}
